<!doctype html><html><head><title>订单管理</title></head><body><div id="app"></div><script type="module" src="/src/main.mjs"></script></body></html>
import { createApp } from 'vue';
import App from './App.vue';
createApp(App).mount('#app');
<script setup>
import OrderList from "./pages/OrderList.vue";
</script>
<template><OrderList /></template>
<script setup>
import { computed, ref } from "vue";
import { filterOrders } from "../order-filter.mjs";
import { orders } from "../data/orders.mjs";
const keyword = ref("");
const status = ref("all");
const visibleOrders = computed(() => filterOrders(orders, { keyword: keyword.value, status: status.value }));
</script>
<template><input v-model="keyword" aria-label="搜索订单" /><select v-model="status"><option value="all">全部</option><option value="paid">已支付</option><option value="pending">待支付</option></select><ul><li v-for="order in visibleOrders" :key="order.id">{{ order.id }} {{ order.customer }}</li></ul></template>
export const orders = [{ id: "AB-001", customer: "Alice", status: "paid" }, { id: "CD-002", customer: "张三", status: "pending" }];
// 空关键词不限制搜索，状态条件与关键词条件同时生效。
export function filterOrders(orders, { keyword = "", status = "all" } = {}) {
  const query = keyword.trim().toLowerCase();
  return orders.filter(order => (status === "all" || order.status === status) && (!query || `${order.id} ${order.customer}`.toLowerCase().includes(query)));
}
// 后续设置页使用，当前订单页未导入。
export const settings = { locale: "zh-CN", pageSize: 20 };
import test from "node:test";
import assert from "node:assert/strict";
import { filterOrders } from "../src/order-filter.mjs";
const orders = [{ id: "A-1", customer: "Alice", status: "paid" }, { id: "B-2", customer: "Bob", status: "pending" }];
test("空关键词保留全部订单", () => {
  assert.deepEqual(filterOrders(orders, { keyword: "" }), orders);
});
